function canonicalFixture(){const grid=5,heights=Float32Array.from({length:25},(_,i)=>i===0?-0:Math.sin(i)),vertices=new Uint16Array(50),triangles=[];for(let z=0;z<grid;z++)for(let x=0;x<grid;x++){const i=z*grid+x;vertices.set([x,z],i*2);if(x<grid-1&&z<grid-1)triangles.push(i,i+grid,i+1,i+1,i+grid,i+grid+1);}return {grid,cell:2,half:4,heights,vertices,triangles:new Uint32Array(triangles)};}
function canonicalReference(input){const position=new Float32Array(input.vertices.length/2*3),uv=new Float32Array(input.vertices.length);for(let i=0;i<input.vertices.length/2;i++){const x=input.vertices[i*2],z=input.vertices[i*2+1];position.set([x*input.cell-input.half,input.heights[z*input.grid+x],z*input.cell-input.half],i*3);uv.set([x/(input.grid-1),z/(input.grid-1)],i*2);}return {position,uv,index:input.triangles};}
function canonicalDecoded(chunk,input){const position=new Float32Array(chunk.height.length*3),uv=new Float32Array(chunk.height.length*2);for(let i=0;i<chunk.height.length;i++){const x=chunk.gridPosition[i*2],z=chunk.gridPosition[i*2+1];position.set([x*input.cell-input.half,chunk.height[i],z*input.cell-input.half],i*3);uv.set([x/(input.grid-1),z/(input.grid-1)],i*2);}return {position,uv,index:chunk.index};}
function threeBounds(position){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(position,3));g.computeBoundingBox();g.computeBoundingSphere();return {min:g.boundingBox.min.toArray(),max:g.boundingBox.max.toArray(),center:g.boundingSphere.center.toArray(),radius:g.boundingSphere.radius};}
function canonicalExact(a,input,label,limit=65535){const r=a.canonical(input,limit),ref=canonicalReference(input),old=partitionTerrain(ref,limit);assert.equal(r.chunks.length,old.chunks.length,label+': chunk count');assert.equal(r.triangles,input.triangles.length/3,label+': triangle count');assert.deepEqual(r.bounds,threeBounds(ref.position),label+': root actual Three bounds');for(let i=0;i<old.chunks.length;i++){const actual=canonicalDecoded(r.chunks[i],input),expected=old.chunks[i];for(const key of ['position','uv','index'])assert.deepEqual(Buffer.from(actual[key].buffer),Buffer.from(expected[key].buffer),label+': ordered triangle/attribute bits '+key);assert.deepEqual(r.chunks[i].bounds,threeBounds(expected.position),label+': chunk actual Three bounds');}return r;}
